// Generate the shared-project port from the maintained Attendance schema.
// All tables/functions/indexes/constraints are namespaced; parking SQL is never
// an input. Generated files are reviewed/tested before deployment.
import fs from 'node:fs';
import crypto from 'node:crypto';
const root=new URL('../',import.meta.url);
const check=process.argv.includes('--check');
function write(file,content) {
 if(check) {
  if(fs.readFileSync(file,'utf8')!==content)throw new Error('Generated Attendance file is stale: '+file.pathname);
 } else fs.writeFileSync(file,content);
}
const source=fs.readFileSync(new URL('../../aero-attendance/setup/schema.sql',import.meta.url),'utf8');
const names=new Set();
for(const regex of [/create\s+table\s+if\s+not\s+exists\s+(\w+)/gi,/create\s+(?:or\s+replace\s+)?function\s+(\w+)/gi,/create\s+(?:or\s+replace\s+)?view\s+(\w+)/gi,/create\s+(?:unique\s+)?index\s+if\s+not\s+exists\s+(\w+)/gi,/add\s+constraint\s+(\w+)/gi]) for(const m of source.matchAll(regex))names.add(m[1]);
const tables=[...source.matchAll(/create\s+table\s+if\s+not\s+exists\s+(\w+)/gi)].map(m=>m[1]);
for(const name of tables) for(const m of source.matchAll(new RegExp('\\b'+name+'_\\w+','g')))names.add(m[0]);
const pattern=new RegExp('\\b('+[...names].sort((a,b)=>b.length-a.length).join('|')+')\\b','g');
const functions=new Set([...source.matchAll(/create\s+(?:or\s+replace\s+)?function\s+(\w+)/gi)].map(m=>m[1]));
let sql=source.replace(pattern,(n,_capture,offset)=>functions.has(n)&&!/^\s*\(/.test(source.slice(offset+n.length))?n:'aero_'+n);
// No background jobs or push destination until the pilot recipient gate and
// sender are deployed. In particular, never reuse the old project's webhook.
sql=sql.replace(/insert into aero_push_config \(function_url\)[\s\S]*?on conflict \(id\) do nothing;/,'-- Push configured explicitly at release.');
sql=sql.replace(/^select cron\.(?:un)?schedule[^\n]*$/gm,'-- Timer configured explicitly at release.');
// Close/break operations lock the open row before calculating its break time,
// so concurrent taps cannot subtract the same break twice.
for(const name of ['aero_clock_out','aero_end_break']) {
 const definitions=[...sql.matchAll(new RegExp('create or replace function '+name+'\\([\\s\\S]*?\\n\\$\\$;','g'))];
 const last=definitions.at(-1)?.[0];
 if(!last)throw new Error('Missing '+name);
 let locked=last.replace('order by clock_in_at desc limit 1;','order by clock_in_at desc limit 1 for update;');
 if(name==='aero_clock_out')locked=locked.replace('begin\n',`begin\n  if p_lat is not null and not(p_lat between -90 and 90) then p_lat:=null;end if;\n  if p_lng is not null and not(p_lng between -180 and 180) then p_lng:=null;end if;\n`);
 sql+='\n'+locked;
}
sql+='\n'+fs.readFileSync(new URL('attendance-shared-gates.sql',import.meta.url),'utf8');
sql='begin;\n'+sql.replace(/^(?:begin|commit);\s*$/gmi,'')+'\ncommit;\n';
const header='-- GENERATED by node src/build-attendance.mjs; edit the source/gates, then regenerate.\n-- Attendance schema SHA256: '+crypto.createHash('sha256').update(source).digest('hex')+'\n';
write(new URL('setup/136-attendance-shared.sql',root),header+sql);
write(new URL('../../aero-attendance/shared-names.json',import.meta.url),JSON.stringify({tables,functions:[...source.matchAll(/create\s+(?:or\s+replace\s+)?function\s+(\w+)/gi)].map(m=>m[1])},null,2)+'\n');
const senderSource=fs.readFileSync(new URL('../../aero-attendance/supabase/functions/send-push/index.ts',import.meta.url),'utf8');
let sender=senderSource.replace('npm:@supabase/supabase-js@2"','npm:@supabase/supabase-js@2.118.0"')
 .replace(/\.from\("(\w+)"\)/g,(_,table)=>'.from("aero_'+table+'")')
 .replace(/\b(companies|profiles|worksites)(![a-zA-Z0-9_]+)?\(/g,(_,table,constraint)=>table+':aero_'+table+(constraint?'!aero_'+constraint.slice(1):'')+'(');
sender=sender.replace('const ids = [...new Set(userIds)];',`const {data: eligible, error: eligibilityError} = await db.rpc('aero_push_recipients', {p_users: [...new Set(userIds)]});
  if (eligibilityError) throw eligibilityError;
  const ids = (eligible ?? []).map((row: {user_id: string}) => row.user_id);`);
const senderDir=new URL('supabase/functions/aero-send-push/',root);
if(!check)fs.mkdirSync(senderDir,{recursive:true});
write(new URL('index.ts',senderDir),'// GENERATED by src/build-attendance.mjs\n'+sender);
console.log(check?'Generated Attendance files match their maintained sources':'Generated isolated aero_* schema and browser name manifest');
